                        };
                    }
                    groups[catId].teams[teamId].students.push(stu);
                });

                const sortedCatIds = Object.keys(groups).sort((a, b) => {
                    const idxA = allCategories.findIndex(c => c.id === a);
                    const idxB = allCategories.findIndex(c => c.id === b);
